<?php

namespace Database\Seeders;

use App\Models\FaqKnowledgeBase;
use Illuminate\Database\Seeder;

/**
 * The chatbot's built-in answers. Runs on every deploy (start.sh), keyed on the
 * question text, so editing an answer here updates it in place.
 *
 * Matching without an AI key is by keyword overlap (ChatbotService::processQuery):
 * only words longer than 3 letters count, compared exactly — so keywords list
 * plural/verb forms and words distinctive to each answer. With a Gemini key, all
 * active entries are the AI's context.
 *
 * Answers mirror the live rules (clock-in window, interview windows, promissory
 * notes, claim stubs…). No peso amounts and no stipend frequency are stated on
 * purpose — the DSA announces those.
 */
class FaqSeeder extends Seeder
{
    /** Superseded questions: switched off (not deleted) so the live table stays clean. */
    private const RETIRED = [
        'How do I record my time-in and time-out?', // merged into "How do I clock in for attendance?"
    ];

    public function run(): void
    {
        $faqs = [
            // ── Accounts & signing in ─────────────────────────────────────────
            ['category' => 'account', 'question' => 'How do I create a SWAP Portal account?', 'answer' => 'Open the SWAP Portal and choose Register (it is available while the DSA has the application period open). Use your MSU-Main student email ending in @s.msumain.edu.ph, your 9-digit student ID, and a password of at least 8 characters with upper- and lower-case letters and a number. After registering, open the verification link sent to your email — you can sign in only after verifying.', 'keywords' => ['register', 'registration', 'signup', 'create', 'account', 'sign'], 'sort_order' => 1],
            ['category' => 'account', 'question' => 'Why can’t I register with my Gmail or personal email?', 'answer' => 'Registration only accepts your MSU-Main student email, the one ending in @s.msumain.edu.ph. Personal addresses (Gmail, Yahoo, etc.) and staff addresses are refused. If you do not have your student email yet, ask the university’s registrar or ICT office.', 'keywords' => ['gmail', 'yahoo', 'personal', 'institutional', 'student', 'email', 'domain'], 'sort_order' => 2],
            ['category' => 'account', 'question' => 'What student ID number should I use when registering?', 'answer' => 'Enter your student ID as exactly 9 digits, numbers only (for example 200912345). Each student ID can be registered only once — if it says the ID is already taken, you may already have an account; try signing in or resetting your password.', 'keywords' => ['student', 'number', 'digits', 'idnumber', 'taken'], 'sort_order' => 3],
            ['category' => 'account', 'question' => 'Why does it say the application period is closed?', 'answer' => 'The DSA opens and closes the application period each semester. While it is closed, new accounts and new applications cannot be submitted. Watch the SWAP Portal home page or DSA announcements for the next opening.', 'keywords' => ['closed', 'period', 'open', 'opening', 'started', 'available'], 'sort_order' => 4],
            ['category' => 'account', 'question' => 'I didn’t receive my verification email. What should I do?', 'answer' => 'Check your spam or junk folder first. On the sign-in page, use “Resend verification email” and enter your student email — wait a minute between tries. Once you open the link, your account is activated and you can sign in.', 'keywords' => ['verification', 'verify', 'resend', 'receive', 'received', 'spam', 'activate', 'activation'], 'sort_order' => 5],
            ['category' => 'account', 'question' => 'Why can’t I sign in?', 'answer' => 'Common reasons: the email or password is wrong (check for typos and Caps Lock); your email is not verified yet (open the verification link or resend it); your account was deactivated (contact the DSA Office); or there were too many attempts in a short time (wait a minute and try again). If you forgot your password, use “Forgot password”.', 'keywords' => ['login', 'signin', 'cannot', 'incorrect', 'credentials', 'wrong', 'blocked'], 'sort_order' => 6],
            ['category' => 'account', 'question' => 'I forgot my password. How do I reset it?', 'answer' => 'On the sign-in page choose “Forgot password”, enter your email, and open the reset link we send you. Set a new password with at least 8 characters, upper- and lower-case letters, and a number. The link expires after a while — request a new one if it no longer works.', 'keywords' => ['forgot', 'forgotten', 'reset', 'password', 'recover', 'link'], 'sort_order' => 7],
            ['category' => 'account', 'question' => 'Why was I signed out of the portal?', 'answer' => 'For security, each sign-in lasts up to 7 days. You are also signed out on your other devices when you change your password, and immediately if the DSA deactivates your account. Simply sign in again.', 'keywords' => ['signed', 'logged', 'logout', 'session', 'expired', 'again'], 'sort_order' => 8],
            ['category' => 'account', 'question' => 'My account says it has been deactivated. What now?', 'answer' => 'A deactivated account cannot sign in or use the portal. Only the DSA can reactivate it — email dsa@msumain.edu.ph or visit the DSA Office with your student ID.', 'keywords' => ['deactivated', 'disabled', 'inactive', 'suspended', 'reactivate'], 'sort_order' => 9],
            ['category' => 'account', 'question' => 'How do I update my profile or change my password?', 'answer' => 'Open the Profile page from the sidebar or your photo in the top bar. You can update your details and photo (JPG, PNG or WEBP up to 4 MB), save your digital signature, and change your password by entering your current password and a new one. Changing your password signs you out on your other devices.', 'keywords' => ['profile', 'password', 'update', 'account', 'change', 'photo', 'picture'], 'sort_order' => 10],
            ['category' => 'account', 'question' => 'How do supervisors and DSA staff get an account?', 'answer' => 'Staff accounts are created by invitation. A DSA admin sends an invitation email; open the link within 3 days, set your name and password, and your account is ready with the right role. If the link has expired, ask the DSA for a new invitation.', 'keywords' => ['staff', 'invitation', 'invite', 'invited', 'supervisor', 'account'], 'sort_order' => 11],

            // ── Eligibility ───────────────────────────────────────────────────
            ['category' => 'eligibility', 'question' => 'Who is eligible to apply for the SWAP program?', 'answer' => 'SWAP is for qualified MSU students who need financial support to stay in school. Priority goes to 3rd, 4th and 5th year college students carrying at least 15 units this semester (freshmen and sophomores may apply but get the least priority). Under BOR Res. No. 6, s. 1992, assistantships are academic — in instruction or research — and related to your field.', 'keywords' => ['eligible', 'eligibility', 'qualify', 'qualified', 'requirement', 'requirements', 'financial', 'units'], 'sort_order' => 12],
            ['category' => 'eligibility', 'question' => 'Can graduating students apply for SWAP?', 'answer' => 'Yes. Graduating students may apply, and may carry fewer than 15 units if it is their last load.', 'keywords' => ['graduate', 'graduating', 'senior', 'last', 'load'], 'sort_order' => 13],
            ['category' => 'eligibility', 'question' => 'Can first or second year students apply?', 'answer' => 'Yes, freshmen and sophomores are still eligible to apply, but they are given the least priority. 3rd, 4th and 5th year students come first.', 'keywords' => ['freshman', 'freshmen', 'sophomore', 'sophomores', 'first', 'second', 'year'], 'sort_order' => 14],
            ['category' => 'eligibility', 'question' => 'Can I apply every semester?', 'answer' => 'Yes, applications re-open every semester. You can have only one application in progress at a time and one application per academic year and semester. Current recipients use Renewal instead of a new application.', 'keywords' => ['every', 'semester', 'again', 'reapply', 'next'], 'sort_order' => 15],

            // ── Applying ──────────────────────────────────────────────────────
            ['category' => 'application', 'question' => 'What documents are required for the SWAP application?', 'answer' => 'Upload four documents with your application: your Certificate of Registration (COR), your Grade Card, a Letter of Intent, and a 2×2 photo. Each file can be PDF, JPG or PNG, up to 5 MB.', 'keywords' => ['document', 'documents', 'requirement', 'requirements', 'certificate', 'registration', 'grades', 'grade', 'letter', 'intent', 'photo'], 'sort_order' => 16],
            ['category' => 'application', 'question' => 'How do I submit my SWAP application?', 'answer' => 'Register and verify your account, then sign in and open Application. Choose the academic year and semester, upload your COR, Grade Card, Letter of Intent and 2×2 photo, and submit. You will be notified in the portal (and by email) at every step: review, interview, and decision. Portal: https://swap-project-nqqw.vercel.app/', 'keywords' => ['submit', 'apply', 'application', 'portal', 'online', 'steps', 'start'], 'sort_order' => 17],
            ['category' => 'application', 'question' => 'How long does the application review take?', 'answer' => 'The DSA reviews applications during and after the application period. Review time depends on the number of applicants, so there is no fixed number of days — you will get a notification (and email) as soon as your application moves to review, when an interview is scheduled, and when a decision is made.', 'keywords' => ['review', 'processing', 'waiting', 'decision', 'days', 'long', 'result'], 'sort_order' => 18],
            ['category' => 'application', 'question' => 'How do I check my application status?', 'answer' => 'Sign in and open your Dashboard or your application. It shows the current status — Submitted, Under review, Interview scheduled, Approved, or Rejected (with the DSA’s remarks) — plus your interview details. You also get a notification whenever the status changes.', 'keywords' => ['status', 'dashboard', 'check', 'application', 'progress', 'track'], 'sort_order' => 19],
            ['category' => 'application', 'question' => 'What do the application statuses mean?', 'answer' => 'Submitted: received, waiting for the DSA. Under review: the DSA is checking your documents. Interview scheduled: see the date, time and venue or meeting link. Approved: you passed and will be assigned to an office. Rejected: not accepted this time; the DSA’s remarks explain why.', 'keywords' => ['statuses', 'meaning', 'mean', 'submitted', 'approved', 'rejected', 'scheduled'], 'sort_order' => 20],
            ['category' => 'application', 'question' => 'Can I cancel or withdraw my application?', 'answer' => 'You can cancel your application only while it is still “Submitted”. Once the DSA starts reviewing it, it can no longer be cancelled from the portal — contact the DSA Office if you need to withdraw.', 'keywords' => ['cancel', 'withdraw', 'delete', 'remove', 'undo'], 'sort_order' => 21],
            ['category' => 'application', 'question' => 'Why can’t I submit another application?', 'answer' => 'You can have only one application in progress at a time, and one per academic year and semester. If your application was approved, wait for your office assignment instead of applying again.', 'keywords' => ['another', 'second', 'twice', 'again', 'duplicate', 'progress'], 'sort_order' => 22],
            ['category' => 'application', 'question' => 'My document upload failed. What should I do?', 'answer' => 'Make sure each file is a PDF, JPG or PNG and no larger than 5 MB, then try again. If the upload fails while submitting, the unfinished application is removed automatically so you can simply submit again.', 'keywords' => ['upload', 'uploading', 'failed', 'file', 'size', 'large', 'error'], 'sort_order' => 23],
            ['category' => 'application', 'question' => 'Where can I see the documents I uploaded?', 'answer' => 'Applicants can open the Documents page from the sidebar to view the files attached to their application.', 'keywords' => ['uploaded', 'documents', 'view', 'files', 'attached'], 'sort_order' => 24],

            // ── Interviews ────────────────────────────────────────────────────
            ['category' => 'interview', 'question' => 'What should I expect during the SWAP interview?', 'answer' => 'The interview is a short session with the DSA about your situation, your studies, and why you want to join SWAP. Be on time, and bring your ID and copies of the documents you submitted in case they are asked for.', 'keywords' => ['interview', 'prepare', 'expect', 'bring', 'ready'], 'sort_order' => 25],
            ['category' => 'interview', 'question' => 'When and where are interviews held?', 'answer' => 'Face-to-face interviews are held Monday to Friday between 7:00 AM and 5:00 PM, usually at the Office of the Dean of Student Affairs (DSA). Online interviews can be any day between 8:00 AM and 11:00 PM. Your notification and application page show your exact date, time and venue.', 'keywords' => ['interview', 'schedule', 'venue', 'where', 'time', 'face', 'office'], 'sort_order' => 26],
            ['category' => 'interview', 'question' => 'Where do I find the link for my online interview?', 'answer' => 'The meeting link is in your interview notification and on your application page under the interview details. Join a few minutes early from a device with a working camera and microphone.', 'keywords' => ['online', 'link', 'meeting', 'zoom', 'google', 'meet', 'virtual'], 'sort_order' => 27],
            ['category' => 'interview', 'question' => 'Can I reschedule my interview?', 'answer' => 'Only the DSA can move an interview. If you cannot attend, email dsa@msumain.edu.ph or visit the DSA Office as early as possible. When it is moved, you will get a new notification with the updated date and time.', 'keywords' => ['reschedule', 'change', 'interview', 'date', 'move', 'attend'], 'sort_order' => 28],
            ['category' => 'interview', 'question' => 'What happens if I miss my interview?', 'answer' => 'A missed interview is marked as a no-show, and your application cannot be approved until the interview is rescheduled and held. Contact the DSA Office right away to ask for a new schedule.', 'keywords' => ['missed', 'miss', 'noshow', 'absent', 'late'], 'sort_order' => 29],

            // ── After approval: office placement ─────────────────────────────
            ['category' => 'placement', 'question' => 'What happens after my application is approved?', 'answer' => 'The DSA assigns you to an office and a supervisor. You are notified with the office, its location and your supervisor, and your account becomes a SWAP recipient. Next: add your digital signature on your Profile, then report to your office and start clocking in.', 'keywords' => ['approved', 'after', 'next', 'assignment', 'assigned', 'placement'], 'sort_order' => 30],
            ['category' => 'placement', 'question' => 'Which office will I be assigned to?', 'answer' => 'The DSA decides your office based on its needs and your field of study, since assistantships are tied to your major. You can see your office and supervisor on your Dashboard once you are assigned.', 'keywords' => ['which', 'office', 'assigned', 'assignment', 'placed'], 'sort_order' => 31],
            ['category' => 'placement', 'question' => 'Can my office or supervisor change?', 'answer' => 'Yes, the DSA can move you to another office or supervisor during the semester. You will get a notification with your new office and supervisor, and the new office QR code applies from then on.', 'keywords' => ['transfer', 'reassigned', 'moved', 'change', 'office', 'supervisor', 'new'], 'sort_order' => 32],

            // ── Attendance: clocking in ───────────────────────────────────────
            ['category' => 'attendance', 'question' => 'How do I clock in for attendance?', 'answer' => 'Before you start: save your digital signature on your Profile and turn on your phone’s location. Then, at your office, Monday to Saturday between 6:00 AM and 5:30 PM: scan your office QR code with your phone camera, or open Scan QR, or paste the code on the Attendance page. Take the selfie if your office requires one, and you are clocked in. You must be on the office premises — the portal checks your GPS location.', 'keywords' => ['clock', 'clockin', 'timein', 'attendance', 'scan', 'record', 'start'], 'sort_order' => 33],
            ['category' => 'attendance', 'question' => 'What time can I clock in?', 'answer' => 'Clock-in is open Monday to Saturday, from 6:00 AM to 5:30 PM (Philippine time). It is closed on Sundays and outside those hours.', 'keywords' => ['time', 'hours', 'sunday', 'saturday', 'morning', 'late', 'window', 'open'], 'sort_order' => 34],
            ['category' => 'attendance', 'question' => 'Why won’t the system let me clock in?', 'answer' => 'The message on screen tells you why. Most common: you are outside the office premises (move closer and check your GPS); the QR code is from a different office; location access is off; you have no digital signature yet; a selfie is required; you are already clocked in; you already completed your required hours; it is Sunday or outside 6:00 AM–5:30 PM; you have no active assignment; or the office has no location set yet (tell the DSA).', 'keywords' => ['cannot', 'rejected', 'refused', 'error', 'clock', 'clockin', 'fail', 'failed', 'wont'], 'sort_order' => 35],
            ['category' => 'attendance', 'question' => 'Why is a signature needed before I can clock in?', 'answer' => 'Your saved signature is used to sign your stipend claim stub and your receipt, so the portal requires it before you render any duty. Open your Profile and draw or upload your signature once; the reminder disappears as soon as it is saved.', 'keywords' => ['signature', 'specimen', 'required', 'sign', 'draw', 'clock'], 'sort_order' => 36],
            ['category' => 'attendance', 'question' => 'Why do I have to take a selfie when clocking in?', 'answer' => 'The selfie is proof that you were at your office. It is required unless one of your office’s supervisors has turned it off. Allow camera access when asked; if the photo fails to save, your clock-in still goes through.', 'keywords' => ['selfie', 'photo', 'camera', 'picture', 'face'], 'sort_order' => 37],
            ['category' => 'attendance', 'question' => 'Why do I need to enable location, and what is geofencing?', 'answer' => 'Geofencing confirms you are physically at your assigned office when you clock in. The portal compares your phone’s GPS with the office location and its allowed radius (with some tolerance for a weak signal). This stops attendance from being recorded off-site, so keep location on and let the GPS settle before scanning.', 'keywords' => ['geofencing', 'geofence', 'location', 'enable', 'premises', 'radius'], 'sort_order' => 38],
            ['category' => 'attendance', 'question' => 'Why does it say my location is unverified?', 'answer' => 'Your attendance was recorded but flagged for your supervisor to double-check. This happens when the GPS fix was weak (accuracy worse than 100 m), when the exact same coordinates were reused from an earlier log, or when the distance from your last clock-in would need an impossible travel speed. Clock in on a phone with GPS on, ideally near a window or outdoors.', 'keywords' => ['unverified', 'location', 'accuracy', 'flagged', 'flag', 'weak', 'signal'], 'sort_order' => 39],
            ['category' => 'attendance', 'question' => 'It says I am already clocked in. What should I do?', 'answer' => 'You still have an open session — clock out first (submit your narrative, then scan your office QR). If the session is from an earlier day, it closes automatically after 12 hours; after that you can clock in again.', 'keywords' => ['already', 'clocked', 'open', 'session', 'twice'], 'sort_order' => 40],
            ['category' => 'attendance', 'question' => 'Can I clock in after completing my required hours?', 'answer' => 'No. Once your verified hours reach your required hours for the semester, clock-in stops — your service for the term is complete.', 'keywords' => ['completed', 'complete', 'finished', 'done', 'required', 'enough'], 'sort_order' => 41],
            ['category' => 'attendance', 'question' => 'What are the ways to scan my office QR code?', 'answer' => 'Three ways, all equivalent: point your phone camera at the office QR (it opens the portal and clocks you in), open Scan QR in the sidebar, or copy the QR code text and paste it on the Attendance page. The QR code is displayed at your office — ask your supervisor if you cannot find it.', 'keywords' => ['scan', 'scanner', 'camera', 'paste', 'code', 'qrcode', 'ways'], 'sort_order' => 42],

            // ── Attendance: clocking out ──────────────────────────────────────
            ['category' => 'clock_out', 'question' => 'How do I clock out?', 'answer' => 'On the Attendance page tap Clock Out. First fill in your narrative report (what you worked on — at least 10 characters for the summary and the activities), then scan your own office QR code. Your session then goes to your supervisor for verification.', 'keywords' => ['clockout', 'timeout', 'leave', 'leaving', 'finish', 'end', 'out'], 'sort_order' => 43],
            ['category' => 'clock_out', 'question' => 'What is a narrative report?', 'answer' => 'A narrative report is a short summary of a work session: what you did, the activities you completed, and any challenges. It is required before a normal clock-out (one per session), and your supervisor reads it when verifying your hours.', 'keywords' => ['narrative', 'report', 'summary', 'activities', 'tasks'], 'sort_order' => 44],
            ['category' => 'clock_out', 'question' => 'What happens if I forget to clock out?', 'answer' => 'If your office uses geofencing and you leave the premises for about 10 minutes while clocked in, you are clocked out automatically (no narrative needed). Any session left open longer than 12 hours is closed automatically and credited at most 12 hours. Still, always clock out properly so your hours are accurate.', 'keywords' => ['forget', 'forgot', 'forgotten', 'clockout', 'automatic', 'stale'], 'sort_order' => 45],
