            ['category' => 'hours', 'question' => 'How many service hours are required per semester?', 'answer' => 'The usual requirement is 200 hours per semester in your assigned office. Your exact number is set on your assignment and shown on your Hours page and Dashboard; your supervisor can adjust it.', 'keywords' => ['hours', 'service', 'requirement', 'semester', 'many', 'required', 'render'], 'sort_order' => 48],
            ['category' => 'hours', 'question' => 'How do I see my rendered hours and progress?', 'answer' => 'Open the Hours page to see your verified, pending and remaining hours, with a progress bar toward your requirement. For printable records, use the Duty Slip page (weekly slip or semester service report).', 'keywords' => ['rendered', 'progress', 'remaining', 'track', 'total', 'hours'], 'sort_order' => 49],
            ['category' => 'hours', 'question' => 'How does my supervisor verify my hours?', 'answer' => 'After you clock out, the session goes to your office supervisor as pending. They check your time and narrative report, then verify it or reject it with feedback. Only verified hours count toward your requirement and your stipend.', 'keywords' => ['verify', 'verification', 'verified', 'supervisor', 'approve', 'pending'], 'sort_order' => 50],
