            ['category' => 'hours', 'question' => 'What happens if my supervisor rejects my attendance log?', 'answer' => 'You receive a notification with your supervisor’s feedback. Rejected hours do not count toward your required hours or appear on your duty slip. Talk to your supervisor if you think it was a mistake.', 'keywords' => ['reject', 'rejected', 'supervisor', 'feedback', 'invalid', 'declined'], 'sort_order' => 52],
            ['category' => 'hours', 'question' => 'What are bonus hours?', 'answer' => 'Bonus hours are extra hours credited for approved work outside a normal clock-in, such as an event. Hours added by your supervisor count right away; hours added by the DSA need your supervisor’s approval first. They appear in the BONUS column of your duty slip and are included in your total.', 'keywords' => ['bonus', 'extra', 'manual', 'added', 'event'], 'sort_order' => 53],
            ['category' => 'hours', 'question' => 'Can my required hours change during the semester?', 'answer' => 'Yes. Your supervisor can adjust your required hours. If the DSA requests a change, your supervisor approves or rejects it first. Your Hours page always shows the current number.', 'keywords' => ['change', 'adjust', 'required', 'increase', 'decrease', 'hours'], 'sort_order' => 54],

            // ── Duty slips ────────────────────────────────────────────────────
