            ['category' => 'duty_slip', 'question' => 'Why are the signatures missing from my duty slip?', 'answer' => 'Your supervisor’s and your signature appear only when every day on that slip has been verified and both of you have saved a digital signature. Ask your supervisor to verify any pending days, and make sure your own signature is saved on your Profile.', 'keywords' => ['signatures', 'signature', 'missing', 'blank', 'duty', 'slip', 'unsigned'], 'sort_order' => 56],
