            // ── Stipend & claim stubs ─────────────────────────────────────────
            ['category' => 'stipend', 'question' => 'How much is the SWAP stipend?', 'answer' => 'The amount is set by the DSA based on the approved budget and is announced by the DSA Office. When your stipend is released, the exact amount is printed on your claim stub.', 'keywords' => ['stipend', 'allowance', 'amount', 'money', 'much', 'salary'], 'sort_order' => 62],
            ['category' => 'stipend', 'question' => 'When is the stipend released?', 'answer' => 'Your stipend is released after your required service hours are verified by your supervisor (or after an approved promissory note, if you fell short). The DSA then issues your claim stub and you are notified right away.', 'keywords' => ['release', 'released', 'when', 'payment', 'receive', 'stipend', 'schedule'], 'sort_order' => 63],
            ['category' => 'stipend', 'question' => 'How do I claim my stipend?', 'answer' => 'When you are notified that your stipend is ready: open Stipend, download your claim stub (PDF), and bring it to the University Banking Office. After you receive the money, tap Confirm receipt on the Stipend page and enter the name of the releasing officer or cashier. That completes your receiving slip.', 'keywords' => ['claim', 'claiming', 'collect', 'banking', 'cashier', 'receipt', 'stipend'], 'sort_order' => 64],
            ['category' => 'stipend', 'question' => 'What is a claim stub?', 'answer' => 'A claim stub is the official slip for your stipend. It has a control number (SWAP-STP-…), the amount and period, and the signatures of your supervisor and the DSA. You download it from the Stipend page and present it at the Banking Office.', 'keywords' => ['claim', 'stub', 'slip', 'control', 'number'], 'sort_order' => 65],
