            ['category' => 'stipend', 'question' => 'Why am I not eligible for a stipend yet?', 'answer' => 'A stipend is released only when your verified hours meet your requirement (or you have an approved promissory note). Pending or rejected hours do not count. You also cannot get a second stipend for a semester that already has one.', 'keywords' => ['eligible', 'eligibility', 'stipend', 'qualified', 'listed', 'released'], 'sort_order' => 67],
